bool HasSmallRemainder(
  int64_t number
) {
  int64_t remainder = common::FloorMod(number, 7);
  return remainder < 3;
}

bool IsWithinDistance(
  int64_t number,
  int64_t center,
  int64_t distance
) {
  return std::abs(number - center) <= distance;
}

bool IsNegative(
  int64_t number
) {
  return (
    (
      -number > 0
      && -(-number) < 0
    )
  );
}

bool IsLengthAligned(
  const std::wstring& text,
  int64_t alignment
) {
  return (
    common::FloorMod(
      static_cast<int64_t>(common::LenStr(text)),
      alignment
    ) == 0
  );
}

